<header class="student-test-hero"><div><span class="module-eyebrow">ONLINE ASSESSMENT</span><h1><?=e($test['title'])?></h1><p><?=e($test['instructions']?:'Read every question carefully and submit once complete.')?></p></div><div class="attempt-progress"><?php if($uploadOnly):?><strong>Upload only</strong><small>Photos or PDF · up to <?=$maxPages?> pages</small><?php else:?><strong><span data-answered-count>0</span> / <?=count($test['questions'])?></strong><small>answered</small><?php endif?><div><?=$test['duration_minutes']?> minutes</div><?php if(!empty($deadline)):?><div class="test-timer" data-test-deadline="<?=(int)$deadline?>" data-server-now="<?=time()?>" role="timer" aria-live="off"><span data-timer-label>Time left</span> <b data-timer-value>—</b></div><?php endif?></div></header>
