<?php foreach($test['questions']as$i=>$q):?><article class="answer-card" data-answer-card><header class="answer-card__head"><span><?=($i+1)?></span><h2><?=e($q['question_text']?:'Open the attached question file below.')?></h2><small><?=e($q['marks'])?> marks</small></header><div class="answer-card__body">
