<?php if(!$uploadOnly&&$q['question_type']==='mcq'):?><div class="student-mcq"><?php foreach($q['options']as$n=>$option):?><label class="mcq-option"><input type="radio" name="answer[<?=$q['id']?>]" value="<?=$n?>" required><span><?=chr(65+$n)?></span><strong><?=e($option)?></strong></label><?php endforeach?></div>
<?php elseif(!$uploadOnly):?><label class="builder-field"><span>Your answer</span><textarea name="answer[<?=$q['id']?>]" placeholder="Start writing your answer here..."></textarea></label><label class="student-upload" data-page-upload data-max-pages="<?=$maxPages?>" data-pages-label="Question <?=($i+1)?>"><i data-lucide="image-plus"></i><span><strong>Add photos of your handwritten answer</strong><small>JPG, PNG or PDF · up to <?=$maxPages?> pages</small></span><input type="file" name="answer_attachment[<?=$q['id']?>][]" accept="image/jpeg,image/png,application/pdf,.jpg,.jpeg,.png,.pdf" multiple></label><?php endif?></div></article><?php endforeach?>
<?php if($uploadOnly):?><section class="module-card"><div class="module-card__body"><h2>Submit your work</h2><p>Take a clear photo of every answer page, or upload photos/PDF from your device. Check each page, then press Submit.</p><label class="student-upload" data-page-upload data-required data-max-pages="<?=$maxPages?>" data-pages-label="Solved paper"><i data-lucide="camera"></i><span><strong>Add pages of your solved paper</strong><small>JPG, PNG or PDF · up to <?=$maxPages?> pages</small></span><input type="file" name="solved_paper[]" accept="image/jpeg,image/png,application/pdf,.jpg,.jpeg,.png,.pdf" multiple required></label></div></section><?php endif?>
<footer class="test-submit-bar"><span class="test-submit-bar__summary" data-submit-summary hidden></span><button class="btn btn--primary" data-submit-button><i data-lucide="send"></i><span data-submit-text>Submit final answers</span></button></footer></form>
